$client=customer_for_user($data);
$clientVehicles=array_values(array_filter($data['vehicles'],fn($v)=>(int)$v['customer_id']===(int)($client['id']??0)));
$clientVehicleIds=array_map(fn($v)=>(int)$v['id'],$clientVehicles);
$clientServices=array_values(array_filter($data['services'],fn($s)=>in_array((int)$s['vehicle_id'],$clientVehicleIds,true)));
$clientAppointments=array_values(array_filter($data['appointments'],fn($a)=>(int)$a['customer_id']===(int)($client['id']??0)));
$catalog=service_catalog();
$diagnosis=$_SESSION['portal_diagnosis']??null;
$activeAppointments=count(array_filter($clientAppointments,fn($a)=>in_array(appointment_status($data,$a),['pending','accepted','in_progress'],true)));
$completedServices=count(array_filter($clientServices,fn($s)=>($s['status']??'completed')==='completed'));
?>
